"""Legacy-compatible EXPORT_ACCT fixed-width record formatting."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if value == "":
        value = 0

    number = Decimal(str(value))
    precision = max(64, len(number.as_tuple().digits) + abs(number.as_tuple().exponent) + 4)

    with localcontext() as context:
        context.prec = precision
        cents = (number * Decimal(100)).to_integral_value(
            rounding=ROUND_HALF_UP
        )

    return str(int(cents)).zfill(width)


def format_account(row: dict) -> str:
    """Return one 77-character legacy EXPORT_ACCT record."""
    account_id = _fixed(_value(row, "ACCT_ID"), 10)
    account_name = _fixed(_value(row, "ACCT_NM"), 40)
    region_code = _fixed(_value(row, "REGION_CD"), 3)
    annual_revenue = _zpad_cents(_value(row, "ANN_REV"), 15)

    credit_hold = _value(row, "CRED_HOLD")
    if credit_hold == "":
        credit_hold = "N"
    else:
        credit_hold = str(credit_hold)

    create_date = _value(row, "CREATE_DT")
    if create_date == "":
        create_date = "00000000"
    else:
        create_date = str(create_date)

    return (
        account_id
        + account_name
        + region_code
        + annual_revenue
        + credit_hold
        + create_date
    )
